/**
 * What the host app provides for `run_tree`: it owns the WebView, because only the platform has one.
 * The SDK ships an implementation for each platform (`TreeWebViewHost`); an app implements it only
 * to embed the view in its own UI. Once the user closes the page (a Close button, Back, a swipe down),
 * every call but `finish` fails with exactly "the page closed"; a `begin` whose sign-in notice the user
 * declined fails with exactly "the user declined". Either ends the run as `Cancelled`, and nothing is
 * posted.
 */
@_spi(ZktlsLab) public protocol TreeHost : AnyObject {
    
    /**
     * Presents the WebView on `login_url` with the bridge injected at every document start, telling
     * it the URL substrings it records nothing on. `policy` decides every navigation, popup, bridge
     * message, script run and cookie read; a refusal fails the call that met it with the
     * refusal's reason and host (`navigation_refused: <host>`), which ends the run. Answers how the
     * run's web data is isolated: "profile", "shared" or "ephemeral".
     */
    func begin(loginUrl: String, neverRecord: [String], policy: ConfinementPolicy) async throws  -> String
    
    /**
     * Loads `url` and waits for it, at most `timeout_ms`.
     */
    func navigate(url: String, timeoutMs: UInt64) async throws 
    
    /**
     * Reloads the page.
     */
    func refresh() async throws 
    
    /**
     * The page's URL now.
     */
    func currentUrl() async throws  -> String
    
    /**
     * From the WebView's cookie store, so HttpOnly cookies count. The value is compared, not returned.
     */
    func cookiePresent(domain: String, name: String, value: String?) async throws  -> Bool
    
    /**
     * Whether the page (on `url`'s origin, when given) stores `key`, holding `value` when given. The
     * bridge's `storagePresent`: the value is compared, not returned.
     */
    func localStoragePresent(url: String?, key: String, value: String?) async throws  -> Bool
    
    /**
     * Whether `selector` matches an element on the page.
     */
    func elementPresent(selector: String) async throws  -> Bool
    
    /**
     * The bridge's `pageFetch`.
     */
    func pageFetch(request: TreeFetchRequest) async throws  -> TreeFetchResponse
    
    /**
     * The bridge's `startCapture`.
     */
    func startHeaderCapture(urlPattern: String) async throws 
    
    /**
     * The bridge's `stopCapture`.
     */
    func stopHeaderCapture() async throws 
    
    /**
     * The bridge's `startWatch`.
     */
    func watchResponses(urlPattern: String) async throws 
    
    /**
     * The bridge's `stopWatch`.
     */
    func stopWatching() async throws 
    
    /**
     * The bridge's `drain()`: every event since the last drain, as its JSON, in one crossing.
     */
    func drainEvents() async throws  -> String
    
    /**
     * For the attested read: the cookies of `domains` as `"<domain>\t<name>=<value>"`, as
     * `LoginHost::present_login` returns them. The SDK seals them at once.
     */
    func cookies(domains: [String]) async throws  -> [String]
    
    /**
     * For the attested read: the bridge's `sessionMaterial`, as `"<header>\t<value>"` entries. The SDK
     * seals them at once.
     */
    func sessionMaterial(request: TreeSessionRequest) async throws  -> [String]
    
    /**
     * Runs a function of the pack's script: evaluates `load` in the page, which answers "" or why
     * the script did not load, then calls the bridge's `runScript` with a fresh id and `argument`, and
     * returns the bridge's `script` answer as its JSON. A page that closes or navigates before it answers
     * is `{"error": <why>}`.
     */
    func runScript(request: TreeScriptRequest) async throws  -> String
    
    /**
     * Closes the WebView. Called once, whatever the run's result.
     */
    func finish() async 
    
}

