/**
 * The verified claim `claim` returns: the policy's outputs, signed by the verifier and checked
 * against the trust bundle.
 */
public struct Claim {
    /**
     * The policy's typed outputs.
     */
    public var outputs: [TypedOutput]
    /**
     * The session's nullifier: the same account and statement always give the same value.
     */
    public var nullifierHex: String
    /**
     * The profile the claim was captured against.
     */
    public var profileId: String
    /**
     * The policy the claim was checked against.
     */
    public var policyId: String
    /**
     * The trust bundle epoch the verifier's claim key was signed under.
     */
    public var verifierEpoch: UInt32
    /**
     * When the verifier issued the claim, Unix seconds.
     */
    public var issuedAt: UInt64
    /**
     * When the claim expires, Unix seconds.
     */
    public var expiresAt: UInt64
    /**
     * The verifier's signature over the claim, hex.
     */
    public var signatureHex: String
    /**
     * The claim's canonical encoding, base64. Your backend can verify these bytes
     * itself rather than trusting the app.
     */
    public var encoded: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * The policy's typed outputs.
         */outputs: [TypedOutput], 
        /**
         * The session's nullifier: the same account and statement always give the same value.
         */nullifierHex: String, 
        /**
         * The profile the claim was captured against.
         */profileId: String, 
        /**
         * The policy the claim was checked against.
         */policyId: String, 
        /**
         * The trust bundle epoch the verifier's claim key was signed under.
         */verifierEpoch: UInt32, 
        /**
         * When the verifier issued the claim, Unix seconds.
         */issuedAt: UInt64, 
        /**
         * When the claim expires, Unix seconds.
         */expiresAt: UInt64, 
        /**
         * The verifier's signature over the claim, hex.
         */signatureHex: String, 
        /**
         * The claim's canonical encoding, base64. Your backend can verify these bytes
         * itself rather than trusting the app.
         */encoded: String) {
        self.outputs = outputs
        self.nullifierHex = nullifierHex
        self.profileId = profileId
        self.policyId = policyId
        self.verifierEpoch = verifierEpoch
        self.issuedAt = issuedAt
        self.expiresAt = expiresAt
        self.signatureHex = signatureHex
        self.encoded = encoded
    }
}



extension Claim: Equatable, Hashable {
    public static func ==(lhs: Claim, rhs: Claim) -> Bool {
        if lhs.outputs != rhs.outputs {
            return false
        }
        if lhs.nullifierHex != rhs.nullifierHex {
            return false
        }
        if lhs.profileId != rhs.profileId {
            return false
        }
        if lhs.policyId != rhs.policyId {
            return false
        }
        if lhs.verifierEpoch != rhs.verifierEpoch {
            return false
        }
        if lhs.issuedAt != rhs.issuedAt {
            return false
        }
        if lhs.expiresAt != rhs.expiresAt {
            return false
        }
        if lhs.signatureHex != rhs.signatureHex {
            return false
        }
        if lhs.encoded != rhs.encoded {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(outputs)
        hasher.combine(nullifierHex)
        hasher.combine(profileId)
        hasher.combine(policyId)
        hasher.combine(verifierEpoch)
        hasher.combine(issuedAt)
        hasher.combine(expiresAt)
        hasher.combine(signatureHex)
        hasher.combine(encoded)
    }
}


