/**
 * One call to a function of the pack's script, which the host runs in the page in two steps.
 */
public struct TreeScriptRequest {
    /**
     * JavaScript to evaluate first, in the page: it loads the pack's script into this document once
     * and evaluates to "" when it is loaded, or to why not.
     */
    public var load: String
    /**
     * The argument of the bridge's `runScript`, a JSON object, to pass as it is.
     */
    public var argument: String
    /**
     * How long to wait for the bridge's `script` answer.
     */
    public var timeoutMs: UInt64
    /**
     * The node's cookies. Read each from the WebView's cookie store, HttpOnly ones
     * too, and add them to `argument` as `cookies: [{url, value_prefix, value}]` before calling
     * `runScript`, `value` null when no cookie matches. The values stay in the page: never return them.
     */
    public var cookies: [TreeScriptCookie]

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * JavaScript to evaluate first, in the page: it loads the pack's script into this document once
         * and evaluates to "" when it is loaded, or to why not.
