         */error: String, 
        /**
         * The observed sources, by key. A pack's attested source reaches your backend from the attester.
         */sources: [TreeSource], 
        /**
         * Always empty: the attester signs a pack's claim and posts it to your backend with the result.
         */claim: Claim?, 
        /**
         * Requests the tree made in the page.
         */apiCalls: UInt32, 
        /**
         * The run's length on the phone, in milliseconds.
         */durationMs: UInt64, 
        /**
         * Whether the phone's post of the run's result reached the result URL. The SDK posts it once and
         * never retries. False on a hand-off: the attester posts the result.
         */delivered: Bool, 
        /**
         * Why it did not, for your logs; empty when it did, and on a hand-off.
         */deliveryError: String, 
        /**
         * The result's size as posted, gzipped, in bytes; on a hand-off, the observed result's as
         * uploaded to the attester.
         */resultBytes: UInt64, 
        /**
         * How the run's web data was isolated: "profile", "shared" or "ephemeral".
         */isolation: String, 
        /**
         * The attester accepted the pack's attested read (`Detached` was reported): the app may close.
         * The attester reads the platform, signs the claim and posts the run's result, the observed
         * sources, the attested one and the claim, to the result URL.
         */handedOff: Bool) {
        self.succeeded = succeeded
        self.error = error
        self.sources = sources
        self.claim = claim
        self.apiCalls = apiCalls
        self.durationMs = durationMs
        self.delivered = delivered
        self.deliveryError = deliveryError
        self.resultBytes = resultBytes
        self.isolation = isolation
        self.handedOff = handedOff
    }
}



