/**
 * Where the session is, for a progress bar; `onProgress` receives the matching percentage with each phase.
 */

public enum Phase {
    
    /**
     * The login page is showing.
     */
    case loggingIn
    /**
     * `run_tree` is collecting in the page.
     */
    case collecting
    /**
     * `run_tree` is handing the attested read to the attester: one upload of the session.
     */
    case attesting
    /**
     * `run_tree` handed the attested read to the attester, which accepted it: the app may close. The
     * attester reads the platform, signs the claim and posts the run's result to your backend.
     */
    case detached
    /**
     * Asking the front door for a cell.
     */
    case allocating
    /**
     * Fetching the record through the enclaves.
     */
    case capturing
    /**
     * The record is captured and frozen.
     */
    case captured
    /**
     * Proving the statement to the verifier.
     */
    case proving
    /**
     * The verifier has answered.
     */
    case proved
    /**
     * Checking the signed claim against the trust bundle.
     */
    case claiming
    /**
     * The claim is verified.
     */
    case done
    /**
     * A verb failed; the error says why.
     */
    case failed
}


